return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-09-17 11:07:51+0000','plural-forms'=>'nplurals=6; plural=(n == 0) ? 0 : ((n == 1) ? 1 : ((n == 2) ? 2 : ((n % 100 >= 3 && n % 100 <= 10) ? 3 : ((n % 100 >= 11 && n % 100 <= 99) ? 4 : 5))));','project-id-version'=>'Plugins - All-In-One Security (AIOS) – Security and Firewall - Stable (latest release)','language'=>'ar','messages'=>['Your session has expired. Please log in to continue where you left off.'=>'تم انتهاء الجلسة. يرجى تسجيل الدخول للاستمرار.','Username or Email Address'=>'اسم المستخدم أو البريد الإلكتروني','Please enter your email address and you will receive an email with instructions on how to unlock yourself.'=>'يرجى إدخال عنوان بريدك الإلكتروني ليصلك إليه تعليمات حول كيفية رفع الحظر عن حسابك.','You are here because you have been locked out due to too many incorrect login attempts.'=>'أنت هنا لأنّ تم حظر حسابك لتجاوزك الحد الأقصى لعدد المرات غير صحيحة لتسجيل الدخول.','An email has been sent to you with the unlock instructions.'=>'تم إرسال رسالة إلكترونية لك متضمنةً تعليمات رفع الحظر','Unlock link: %s'=>'رابط رفع الحظر: %s','Username:'=>'اسم المستخدم:','Your registration is pending approval.'=>'الموافقة على التسجيل في وضع الانتظار.','Email Address'=>'عنوان البريد الإلكتروني','Log in'=>'تسجيل الدخول','Remember Me'=>'تذكرني','New password'=>'كلمة مرور جديدة','Username: %s'=>'اسم المستخدم: %s','Register'=>'التسجيل','https://wordpress.org/support/'=>'https://wordpress.org/support/','Please enter a valid email address'=>'يرجى إدخال بريداً إلكترونياً صالحاً','ERROR: Unable to process your request!'=>'خطأ: عدم القدرة على معالجة طلبك!','Log In'=>'تسجيل الدخول','<strong>You have successfully updated WordPress!</strong> Please log back in to see what&#8217;s new.'=>'<strong>تم تحديث ووردبريس بنجاح!</strong> يرجى إعادة تسجيل الدخول لعرض كل جديد.','Registration complete. Please check your email.'=>'تم اكتمال التسجيل. يرجى تفقد بريدك الإلكتروني.','Check your email for your new password.'=>'يرجى تفقد بريدك الإلكتروني للحصول على كلمة المرور الجديدة','Check your email for the confirmation link.'=>'قم بتفقد البريد الإلكتروني للحصول على رابط التأكيد.','You are now logged out.'=>'تم تسجيل الخروج للتوّ','You have logged in successfully.'=>'تم تسجيل الدخول بنجاح.','https://codex.wordpress.org/Cookies'=>'https://codex.wordpress.org/Cookies','Lost your password?'=>'هل نسيت كلمة المرور؟','Registration confirmation will be emailed to you.'=>'سيتم إرسال تأكيد التسجيل عبر البريد الإلكتروني','Register For This Site'=>'التسجيل بالموقع','Registration Form'=>'نموذج التسجيل','Confirm new password'=>'تأكيد كلمة المرور','Strength indicator'=>'مؤشر القوة','Enter your new password below.'=>'يرجى إدخال كلمة المرور الجديدة أدناه.','Your password has been reset.'=>'تم إعادة ضبط كلمة المرور.','The passwords do not match.'=>'كلمات المرور غير متطابقة','Please enter your username or email address. You will receive a link to create a new password via email.'=>'يرجى إدخال اسم المستخدم أو البريد الإلكتروني الخاص بك. سوف تستلم رابطاً لإنشاء كلمة مرور جديدة عبر بريدك الإلكتروني.','Lost Password'=>'نسيت كلمة المرور','Possible reason: your host may have disabled the mail() function.'=>'سبب متوقع: يمكن أن مزود الاستضافة قام بتعطيل وظيفة mail().','The email could not be sent.'=>'لم يتم إرسال البريد الإلكتروني','[%s] Password Reset'=>'إعادة ضبط كلمة مرور [%s]','To reset your password, visit the following address:'=>'لإعادة تعيين كلمة مرورك، تقضل بزيارة الرابط التالي:','If this was a mistake, just ignore this email and nothing will happen.'=>'إذا كان هناك خطأ، فقط تجاهل هذه الرسالة ولن يحدث أي شيء.','Someone has requested a password reset for the following account:'=>'لقد قام أحدهم بطلب إعادة ضبط كلمة المرور للحساب التالي:','<strong>ERROR</strong>: You are not allowed to register because your IP address is currently locked!'=>'<strong>خطأ</strong>: لا يسمح لك بتسجيل الدخول بسبب حظر عنوان الانترنت IP الخاص بك.','You were logged out because you just changed the "admin" username.'=>'لقد تم تسجيل خروجك من الموقع ﻷنّك قمت بتغيير اسم المستخدم "admin".','Please log back in to continue.'=>'يرجى إعادة تسجيل الدخول للاستمرار.','Your session has expired because it has been over %d minutes since your last login.'=>'تم انتهاء صلاحية الجلسة بسبب مرور أكثر من %d دقيقة منذ تسجيل دخولك الأخير.','Site Lockout Notification'=>'إشعار قفل الموقع','<strong>ERROR</strong>: Invalid login credentials.'=>'<strong>خطأ</strong>: معلومات تسجيل دخول غير صحيحة.','Your CAPTCHA answer was incorrect - please try again.'=>'إجابة الكابتشا التي أدخلتها غير صحيحة - يرجى المحاولة مجدداً.','Enter something special:'=>'قم بإدخال قيمة مميزة: ','<strong>ERROR</strong>: Your answer was incorrect - please try again.'=>'<strong>خطأ</strong>: إجابتك غير صحيحة - يرجى المحاولة مجدداً.','The following files were changed on your host'=>'تم تغيير الملفات التالية على الاستضافة الخاصة بك','The following files were removed from your host'=>'تم حذف الملفات التالية من الاستضافة الخاصة بك','The following files were added to your host'=>'تم إضافة الملفات التالية إلى الاستضافة','Login to your site to view the scan details.'=>'تسجيل الدخول لعرض تفاصيل التفحص.','A summary of the scan results is shown below:'=>'يتم عرض ملخص نتائج التفحص أدناه:','twenty'=>'عشرين','nineteen'=>'تسعة عشر','eighteen'=>'ثمانية عشر','seventeen'=>'سبعة عشر','sixteen'=>'ستة عشر','fifteen'=>'خمسة عشر','fourteen'=>'أربعة عشر','thirteen'=>'ثلاثة عشر','twelve'=>'اثنا عشر','eleven'=>'إحدى عشر','ten'=>'عشرة','nine'=>'تسعة','eight'=>'ثمانية','seven'=>'سبعة','six'=>'ستة','five'=>'خمسة','four'=>'أربعة','three'=>'ثلاثة','two'=>'اثنان','one'=>'واحد','Please enter an answer in digits:'=>'يرجى إدخال الإجابة بالأرقام: ','Advanced'=>'متقدم','Intermediate'=>'متوسط','Basic'=>'أساسي','Enable IP blocking for 404 detection'=>'تفعيل حظر عناوين الانترنت المسببة لخطأ 404','Enable manual approval of new registrations'=>'تفعيل الموافقة اليدوية على كل تسجيل جديد','You can view all accounts which have been newly registered via the handy table below and you can also perform bulk activation/deactivation/deletion tasks on each account.'=>'يتم عرض كل الحسابات الجديدة في الجدول أدناه، كما يمكنك القيام بعمليات التفعيل أو التعطيل أو الحذف للحسابات بالجملة.','If you suspect there is a user or users who are logged in which should not be, you can block them by inspecting the IP addresses from the data below and adding them to your blacklist.'=>'إذا اشتبهت بوجود مستخدمين مسجّلين حالياً ممن لا يجب تسجيل دخولهم بالموقع، تستطيع حظر هؤلاء المستخدمين من خلال تفحص عناوين الانترنت IPs الخاصة بهم الموجودة في البيانات أدناه، ومن ثم إضافتها إلى القائمة السوداء.','This tab displays all users who are currently logged into your site.'=>'يتم عرض المستخدمين المسجّلين بالموقع حالياً في هذا التبويب.','(Minutes) The user will be forced to log back in after this time period has elapased.'=>'(بالدقائق) سيتم الطلب من المستخدم تسجيل الدخول بالموقع مرة أخرى بعد مرور هذه الفترة الزمنية','This feature allows you to specify a time period in minutes after which the admin session will expire and the user will be forced to log back in.'=>'تقوم هذه الميزة بتحديد فترة زمنية محددة بالدقائق التي سيتم بعدها انتهاء جلسة المستخدم، وسيتم الطلب من المستخدم تسجيل الدخول مرة أخرى.','<strong>ERROR</strong>: Cookies are blocked due to unexpected output. For help, please see <a href="%1$s">this documentation</a> or try the <a href="%2$s">support forums</a>.'=>'<strong>خطأ</strong>: ملفات الكوكيز محظورة لسبب ما غير متوقّع . للحصول على مساعدة، يرجى الاطلاّع على <a href="%1$s">هذه الوثيقة</a> أو اللجوء إلى <a href="%2$s">منتديات الدعم</a>.','<strong>ERROR</strong>: Cookies are blocked or not supported by your browser. You must <a href="%s">enable cookies</a> to use WordPress.'=>'<strong>خطأ</strong>: ملفات الكوكيز محظورة أو غير مدعومة من قبل متصفحك. يجب عليك <a href="%s">تفعيل الكوكيز</a> لاستخدام ووردبريس.','https://wordpress.org/'=>'https://ar.wordpress.org/','Powered by WordPress'=>'يعمل بواسطة ووردبريس','Reset Password'=>'إعادة تعيين كلمة المرور','Password Reset'=>'إعادة تعيين كلمة المرور','Your password reset link appears to be invalid. Please request a new link below.'=>'يبدو أن رابط إعادة تعيين كلمة المرور انتهت صلاحيته. الرجاء طلب رابط جديد أدناه.','Your password reset link has expired. Please request a new link below.'=>'انتهت صلاحية رابط إعادة تعيين كلمة المرور. الرجاء طلب رابط جديد أدناه.','User registration is currently not allowed.'=>'تسجيل الأعضاء غير متاح حاليًا.','To see a list of all locked IP addresses and ranges go to the %s tab in the dashboard menu.'=>'قم بالذهاب إلى تبويب %s في قائمة الصفحة الرئيسية لعرض قائمة مجال وعناوين الانترنت IPs المحظورة.','If the maximum number of failed login attempts for a particular IP address occur within this time period the plugin will lock out that address'=>'إذا تم تجاوز العدد الأقصى لمحاولات تسجيل الدخول الخاصة بعنوان انترنت IP ما ضمن هذه الفترة الزمنية، سيتم حظر عنوان الانترنت IP هذا.','Set the value for the maximum login retries before IP address is locked out'=>'قم بوضع قيمة العدد الأقصى لمحاولات تسجيل الدخول قبل حظر عنوان الانترنت IP','You may also want to checkout our %s feature for another secure way to protect against these types of attacks.'=>'يمكنك أيضاً الإطلاع على ميزة %s التي تعتبر طريقة آمنة أخرى للحماية من هذا النوع من الهجمات.','Apart from choosing strong passwords, monitoring and blocking IP addresses which are involved in repeated login failures in a short period of time is a very effective way to stop these types of attacks.'=>'بالإضافة إلى استخدام كلمة مرور قوية لمنع هذا النوع من الهجمات، كذلك يعتبر مراقبة وحظر عناوين الانترنت IPs المتورطة في عمليات تسجيل الدخول المتكررة والفاشلة في فترة زمنية قصيرة طريقة فعّالة للتصدي لهذه الهجمات.','This is where attackers use repeated login attempts until they guess the password.'=>'يحدث ذلك عندما يحاول القراصنة القيام بعمليات تسجيل دخول متعددة حتى يخمنوا كلمة المرور الصحيحة.','1 sec'=>'ثانية','Start typing a password.'=>'قم بكتابة كلمة المرور','This section contains a useful password strength tool which you can use to check whether your password is sufficiently strong enough.'=>'يحتوي هذا القسم على أداة مقياس كلمة المرور، حيث يمكنك معرفة إذا كانت كلمة المرور المختارة قوية بشكل كافي أم لا.','The longer and more complex your password is the harder it is for hackers to "crack" because more complex passwords require much greater computing power and time.'=>'من الصعب تخمين كلمات المرور المكونة من محارف كثيرة ومختلفة، لأنّ ذلك يتطلب أجهزة حاسوب أكثر قوة، كما يتطلب وقت أطول.','Poor password selection is one of the most common weak points of many sites and is usually the first thing a hacker will try to exploit when attempting to break into your site.'=>'تعتبر كلمة المرور الضعيفة مركز الضعف الأكثر شيوعاً لأغلب المواقع، والتي غالباً ما تكون أول شيء يحاول القراصنة استغلاله في محاولاتهم للدخول إلى موقع الويب الخاص بك.','Your site does not have a user account where the display name is identical to the username.'=>'لا يوجد أي حساب في موقع الويب الخاص بك، يكون فيه الاسم العلني نفس اسم المستخدم.','No action required.'=>'لا حاجة للقيام بأي إجراء','From a security perspective, leaving your nickname the same as your user name is bad practice because it gives a hacker at least half of your account\'s login credentials.'=>'من ناحية أمنية، ليس من الجيد إبقاء الاسم المستعار الخاص بك نفس اسم المستخدم، لأنّ ذلك يعطي فرصة للقراصنة لمعرفة نصف معلومات تسجيل الدخول في الموقع.','By default the nickname is set to the login (or user) name of your account.'=>'بشكل افتراضي، يكون الاسم المستعار نفس اسم تسجيل الدخول (اسم المستخدم) لحسابك.','When you submit a post or answer a comment, WordPress will usually display your "nickname".'=>'عادةً ما يقوم ووردبريس بعرض الاسم المستعار الخاص بك عند قيامك بإضافة أي منشور أو أي تعليق.','This is good security practice.'=>'يعتبر هذا ممارسة أمنية جيدة.','NOTE: If you are currently logged in as "admin" you will be automatically logged out after changing your username and will be required to log back in.'=>'ملاحظة: إذا كنت مسجّل الدخول بالموقع باسم مستخدم "admin" الآن، سيتم تسجيل الخروج من حسابك بعد تغيير اسم المستخدم بشكل أتوماتيكي، ومن ثم عليك تسجيل الدخول مجدداً.','Choose a new username for admin.'=>'قم بإدخال اسم مستخدم جديد للمدير.','Password'=>'كلمة المرور','If your chosen server variable fails the plugin will automatically fall back to retrieving the IP address from $_SERVER["REMOTE_ADDR"]'=>'إذا فشل متغير السيرفر المحدد، ستقوم الإضافة تلقائياً بالعودة إلى عنوان الانترنت IP المسترد من $_SERVER["REMOTE_ADDR"]','This feature is not applicable for Windows server installations.'=>'لا تدعم هذه الميزة المواقع المثبتة على سيرفرات ويندوز.','This plugin has detected that your site is running on a Windows server.'=>'اكتشفت هذه الإضافة أن موقعك يعمل على سيرفر ويندوز.','Place custom rules at the top'=>'قم بوضع القواعد المخصصة في أعلى الملف','This feature will allow you to remove the WP generator meta info and other version info from your site\'s pages.'=>'تقوم هذه الميزة بحذف بيانات ووردبريس الوصفية ورقم إصدار النسخة في صفحات موقع الويب الخاص بك.','This setting allows you to enable/disable debug for this plugin.'=>'يتيح هذا الإعداد لك بتفعيل أو تعطيل تصحيح الأخطاء في هذه الإضافة.','When enabled, this feature will print a "forbidden" error rather than the user information.'=>'عند تفعيل هذه الميزة، سيتم عرض خطأ "ممنوع" بدلاً من عرض بيانات المستخدمين.','When admin user is logged in, the feature is automatically disabled for his session.'=>'يتم تعطيل هذه الميزة في جلسة المدير عند تسجيل دخوله بالموقع.','View Blocked IPs'=>'عرض عناوين انترنت IPs المحظورة','blocked'=>'محظور','Export to CSV'=>'التصدير إلى ملف بصيغة CSV','This setting will implement the 6G security firewall protection mechanisms on your site which include the following things:'=>'يقوم هذا الإعداد بتطبيق آلية حماية جدار 6G الناري على الموقع التي تتضمن الأمور التالية:','This feature will also remove the "X-Pingback" header if it is present.'=>'تقوم هذه الميزة بحذف ترويسة "X-Pingback" -إن وجدت-','The feature will still allow XMLRPC functionality on your site but will disable the pingback methods.'=>'تقوم هذه الميزة بتعطيل طرق التنبيهات "pingback " مع إبقاء عمل وظيفة XMLRPC في الموقع.','Leave this feature disabled and use the feature below if you want pingback protection but you still need XMLRPC.'=>'اترك هذه الميزة معطلة واستخدام الميزة أدناه، إذا أردت تفعيل ميزة حماية التنبيهات pingback مع إبقاء عمل وظيفة XMLRPC.','If you still need XMLRPC then uncheck the "Completely Block Access To XMLRPC" checkbox and enable only the "Disable Pingback Functionality From XMLRPC" checkbox.'=>'إذا كنت بحاجة إلى وظيفة XMLRPC، قم بتعطيل "Completely Block Access To XMLRPC"، وقم بتفعيل فقط خيار "تعطيل وظيفة التنبيهات "Pingback" في XMLRPC".','We provide advice for malware cleanup'=>'نقدم نصائح لتنظيف البرمجيات الضارة','Enter one or more email addresses on a new line.'=>'قم بإدخال كل عنوان بريد إلكتروني على سطر مستقل.','Update of the following MySQL view definition failed: %s'=>'فشل في تحديث تعاريف عرض MySQL التالية: %s','Checking for MySQL tables of type "view".....'=>'التحقق من جداول MySQL الخاصة بنوع "عرض".....','NOTE: This feature does NOT use the .htaccess file to permanently block the IP addresses so it should be compatible with all web servers running WordPress.'=>'ملاحظة: لا تستخدم هذه الميزة ملف .htaccess للقيام بالحظر الدائم لعناوين الانترنت IPs، ولذلك فهي متوافقة مع كل برامج الخوادم التي تشغل ووردبريس.','This tab displays the list of all permanently blocked IP addresses.'=>'في هذا التبويب: يتم عرض قائمة عناوين الانترنت IPs المحظورة بشكل دائم.','Wanna know more about the developers behind this plugin?'=>'هل تود معرفة المزيد حول مطوري هذه الإضافة؟','NOTE: If you are hosting your site on WPEngine or a provider which performs server caching, you will need to ask the host support people to NOT cache your renamed login page.'=>'ملاحظة: إذا كان مزود الاستضافة الخاصة بك هو WPEngine  أو أي مزود يقوم بالتخزين المؤقت لملفات الخادم، فعليك إخبار فريق الدعم لهذا المزود بعدم القيام بالتخزين المؤقت لصفحة تسجيل الدخول الجديدة.','Username'=>'اسم المستخدم','Email'=>'البريد الإلكتروني','All round best WordPress security plugin!'=>'أفضل إضافة شاملة مختصة بحماية ووردبريس!','All In One WP Security'=>'إضافة حماية ووردبريس الكل في واحد','Take note of the IP addresses you want blocked and ask the superadmin to add these to the blacklist using the "Blacklist Manager" on the main site.'=>'اكتب عناوين الانترنت IPs التي تريد حظرها واطلب من superadmin إضافة هذه العناوين إلى القائمة السوداء باستخدام "مدير القائمة السوداء" على الموقع الرئيسي.','Only the "superadmin" can block IP addresses from the main site.'=>'يستطيع "superadmin" فقط حظر عناوين الانترنت IPs من الموقع الأساسي.','The plugin has detected that you are using a Multi-Site WordPress installation.'=>'اكتشفت هذه الإضافة أنك تستخدم موقع ووردبريس متعدد المواقع.','By inspecting the IP address data coming from spammers you will be in a better position to determine which addresses or address ranges you should block by adding them to the permanent block list.'=>'بالتحقق من بيانات عناوين الانترنت IPs الخاصة بمرسلي البريد المزعج، سيتم تحسين أداء تحديد مجال عناوين الانترنت أو عناوين الانترنت IPs التي يجب أن تقوم حظرها من خلال إضافتها إلى القائمة السوداء.','This information can be handy for identifying the most persistent IP addresses or ranges used by spammers.'=>'تساعد هذه المعلومات في معرفة عناوين الانترنت IPs المستخدمة باستمرار من قبل مرسلي البريد المزعج.','For Example: If a settings item relies on the domain URL then it may not work correctly when imported into a site with a different domain.'=>'على سبيل المثال: لن تعمل الإعدادات المعتمدة على اسم مجال الموقع عند استيرادها في موقع باسم مجال مختلف.','This can be handy if you wanted to save time by applying the settings from one site to another site.'=>'يساعد ذلك في حفظ الوقت بنقل الإعدادات من موقع لآخر -إذا أردت-','Please choose a file to import your settings from.'=>'يرجى اختيار ملف لاستعادة الإعدادات منه','The above meta information shows which version of WordPress your site is currently running and thus can help hackers or crawlers scan your site to see if you have an older version of WordPress or one with a known exploit.'=>'توضح البيانات الوصفية أعلاه إصدار وردبريس الذي يعمل عليه موقعك حالياً، وقد يساعد ذلك القراصنة أو برامج الزحف على فحص موقعك لمعرفة ما إذا كان لديك إصدار أقدم من وردبريس أو إصدار آخر يحتوي على ثغرات أمنية.','wp-config file to restore from'=>'استعادة ملف wp-config من ','Restore from a backed up wp-config file'=>'الاستعادة من نسخة ملف wp-config الاحتياطية','Save the current wp-config.php file'=>'حفظ ملف wp-config.php الحالي','You can also restore your site\'s wp-config.php settings using a backed up wp-config.php file.'=>'كما يمكنك استعادة إعدادات ملف wp-config.php باستخدام النسخة الاحتياطية من ملف wp-config.php.','This feature allows you to backup and save your currently active wp-config.php file should you need to re-use the the backed up file in the future.'=>'تقوم هذه الميزة بالنسخ الاحتياطي والحفظ لملف wp-config.php المفعّل حالياً، الذي ربما تحتاج لاستعادته مستقبلاً.','Please choose a wp-config.php file to restore from.'=>'يرجى اختيار ملف wp-config.php لاستعادة الإعدادات منه.','.htaccess file to restore from'=>'الاستعادة من ملف .htaccess','Restore from a backed up .htaccess file'=>'الاستعادة من نسخة ملف .htaccess الاحتياطية','Save the current .htaccess file'=>'حفظ ملف .htaccess الحالي','You can also restore your site\'s .htaccess settings using a backed up .htaccess file.'=>'يمكنك استعادة إعدادات ملف .htaccess من النسخة الاحتياطية لهذا الملف.','This feature allows you to backup and save your currently active .htaccess file should you need to re-use the the backed up file in the future.'=>'تقوم هذه الميزة بالنسخ الاحتياطي والحفظ لملف .htaccess المفعّل حالياً، التي ربما تحتاج لاستعادته مستقبلاً.','Your ".htaccess" file is a key component of your website\'s security and it can be modified to implement various levels of protection mechanisms.'=>'يعد ملف ".htaccess" عنصراً أساسياً في أمان موقعك الإلكتروني ويمكن تعديله لتنفيذ مختلف مستويات طرق الحماية.','htaccess backup failed.'=>'فشل في النسخ الاحتياطي لملف htaccess','If you think that some plugin functionality on your site is broken due to a security feature you enabled in this plugin, then use the following option to turn off all the security features of this plugin.'=>'إذا كنت تعتقد أن بعض وظائف الإضافة على موقعك معطلة بسبب ميزة حماية تم تمكينها في هذه الإضافة، فقم باستخدام الخيار التالي لتعطيل جميع ميزات الحماية لهذه الإضافة.','Backup wp-config.php file'=>'النسخ الاحتياطي لملف wp-config.php','Backup .htaccess file'=>'النسخ الاحتياطي لملف .htaccess','Backup your database'=>'النسخ الاحتياطي لقاعدة البيانات','Import/Export'=>'استيراد/تصدير','This feature allows you to prevent other sites from displaying any of your content via a frame or iframe.'=>'تقوم هذا الميزة بمنع المواقع الأخرى من عرض محتوى موقع الويب الخاص بك ضمن frame أو iframe.','This feature allows you to disable the ability to select and copy text from your front end.'=>'تقوم هذه الميزة بمنع تحديد ونسخ النص من الواجهة الأمامية لموقع الويب الخاص بك.','Frames'=>'إطارات المحتوى','Enter a message you wish to display to visitors when your site is in maintenance mode.'=>'يرجى إدخال الرسالة التي تودّ عرضها للزوار عند وضع موقع الويب الخاص بك في وضع الصيانة.','Locking your site down to general visitors can be useful if you are investigating some issues on your site or perhaps you might be doing some maintenance and wish to keep out all traffic for security reasons.'=>'يكون قفل الواجهة الأمامية للموقع مفيداً جداً في حالة القيام باكتشاف وحل بعض المشاكل في الموقع، أو في حالة القيام ببعض عمليات الصيانة والتطوير أو رغبتك بإيقاف زيارة الجمهور العام للموقع لأسباب أمنية.','This feature allows you to put your site into "maintenance mode" by locking down the front-end to all visitors except logged in users with super admin privileges.'=>'تقوم هذه الميزة بوضع الموقع في "وضع الصيانة" بقفل الواجهة الأمامية الأمامية للموقع أمام جميع الزائرين عدا مديري الموقع.','Your account is now active'=>'حسابك مفعّل الآن','Please select some records using the checkboxes'=>'يرجى اختيار بعض القيود بتحديد المربعات المصغرة.','Enter your custom .htaccess rules/directives.'=>'قم بإدخال قواعد/تعليمات .htaccess المخصصة.','If you break your site you will need to access your server via FTP or something similar and then edit your .htaccess file and delete the changes you made.'=>'إذا تعطل الموقع، قم بالوصول إلى ملفات الخادم عبر FTP أو ما يماثله، ثم احذف التغييرات التي قمت بها في .htaccess.','It is your responsibility to ensure that you are entering the correct code!'=>'من مسؤوليتك تأكيد إدخال التعليمات الصحيحة!','Incorrect .htaccess rules or directives can break or prevent access to your site.'=>'قد تسبب قواعد وتعليمات .htaccess الخاطئة عدم إمكانية الوصول إلى الموقع.','It is useful for when you want to tweak our existing firewall rules or when you want to add your own.'=>'يكون هذا مفيد في حالة أردت إضافة قواعد الجدار الناري الخاصة بك أو تعديل القواعد الموجودة للتوّ.','This feature can be used to apply your own custom .htaccess rules and directives.'=>'تستخدم هذه الميزة لإضافة قواعد وتعليمات مخصصة إلى ملف .htaccess.','Check this if you want to enable the logging of 404 events'=>'قم بتحديد هذا إذا أردت تفعيل سجلات أحداث 404.','Such behaviour can mean that a hacker might be trying to find a particular page or URL for sinister reasons.'=>'يعني هذا السلوك أن القراصنة يحاولون إيجاد صفحة معينة أو إيجاد رابطها لأسباب شريرة.','However, in some cases you may find many repeated 404 errors which occur in a relatively short space of time and from the same IP address which are all attempting to access a variety of non-existent page URLs.'=>'ولكن في بعض الحالات تحدث أخطاء 404 بشكل متكرر في فترات متقاربة نسبياً بوساطة نفس عنوان الانترنت IP، الذي يحاول الوصول إلى روابط صفحات متنوعة على الموقع.','A 404 or Not Found error occurs when somebody tries to access a non-existent page on your website.'=>'يحدث خطأ 404 أو خطأ الصفحة غير موجودة عندما يحاول الشخص الوصول إلى صفحة غير موجودة في موقع الويب الخاص بك.','This feature will prevent people from directly hotlinking images from your site\'s pages by writing some directives in your .htaccess file.'=>'تقوم هذه الميزة بمنع الأشخاص من القيام بالربط الساخن لصور موقع الويب الخاص بك بإضافة تعليمات إلى ملف .htaccess.','Due to the fact that the image being displayed on the other person\'s site is coming from your server, this can cause leaking of bandwidth and resources for you because your server has to present this image for the people viewing it on someone elses\'s site.'=>'في الواقع يستهلك عرض صورة موجودة على الخادم الخاص بك على موقع شخص آخر من حجم البيانات المنقولة وموارد الخادم الخاص بك، لأنّ على الخادم الخاص بك توفير هذه الصورة لزائري موقع ذلك الشخص.','Name'=>'الاسم','If the bot fails the checks then the plugin will mark it as being a fake Googlebot and it will block it'=>'إذا تم التحقق أنه بوت مزيف، سيتم تعليمه كبوت مزيف والقيام بحظره.','It will then perform a few tests to verify if the bot is legitimately from Google and if so it will allow the bot to proceed.'=>'بعد ذلك يتم إجراء بعض من الاختبارات للتأكد أنّه بوت غوغل فعلي. إن كان كذلك سيسمح للبوت بالزيارة.','This feature will check if the User Agent information of a bot contains the string "Googlebot".'=>'تقوم هذه الميزة بالتحقق من احتواء معلومات وكيل المستخدم الخاصة بالبوت على اسم "Googlebot".','All other bots from other organizations such as "Yahoo", "Bing" etc will not be affected by this feature.'=>'لن تتأثر البوتات من المنظمات الأخرى مثل الياهو أو البنغ بهذه الميزة.','This feature allows you to block bots which are impersonating as a Googlebot but actually aren\'t. (In other words they are fake Google bots)'=>'تقوم هذه الميزة بحظر البوتات المنتحلة عمل Googlebot وفي الواقع ليس لها علاقة بالغوغل. (بعبارات أبسط هذه بوتات غوغل مزيفة)','Although most of the bots out there are relatively harmless sometimes website owners want to have more control over which bots they allow into their site.'=>'بالرغم أن معظم البوتات غير ضارة، ولكن في بعض الأحيان يرغب مديري المواقع بتحديد البوتات المسموح لها بزيارة الموقع.','%s?'=>'%s?','....and much more.'=>'والكثير ....','4) Stop attackers from manipulating query strings by disallowing illicit characters.'=>'4) منع القراصنة من التلاعب بسلاسل الاستعلام من خلال رفض المحارف غير المسموحة.','3) Guard against the common patterns and specific exploits in the root portion of targeted URLs.'=>'3) الحماية من الأنماط الشائعة أو الثغرات المحددة في جذر الروابط المستهدفة.','2) Block malicious encoded URL characters such as the ".css(" string.'=>'2) حظر محارف الروابط الخبيثة مثل سلسلة  ".css(".','1) Block forbidden characters commonly used in exploitative attacks.'=>'1) حظر المحارف الممنوعة التي تستخدم بشكل شائع في الهجمات الاستغلالية.','This setting will implement the 5G security firewall protection mechanisms on your site which include the following things:'=>'يقوم هذا الإعداد بتطبيق آلية حماية جدار 5G الناري على الموقع التي تتضمن الأمور التالية:','NOTE: Some strings for this setting might break some functionality.'=>'ملاحظة: قد تقوم بعض السلاسل لهذه الميزة بتعطيل بعض وظائف الموقع.','This setting matches for common malicious string patterns and exploits and will produce a 403 error for the hacker attempting the query.'=>'يقوم هذا الإعداد بمقارنة أنماط السلاسل الخبيثة الشائعة، وعرض خطأ 403 عندما يحاول القراصنة القيام بالاستعلام.','This is an advanced character string filter to prevent malicious string attacks on your site coming from Cross Site Scripting (XSS).'=>'تقوم ميزة التصفية المتقدمة لسلاسل المتقدمة بمنع هجمات السلاسل الخبيئة في الموقع والتي تأتي من هجمات XSS.','NOTE: Some of these strings might be used for plugins or themes and hence this might break some functionality.'=>'ملاحظة: قد تستخدم بعض الإضافات أو القوالب هذه السلاسل، وبالتالي قد يؤدي تفعيل هذه الميزة إلى تعطيل بعض وظائف الموقع.','This will help protect you against malicious queries via XSS.'=>'يساعد هذا في الحماية من الاستعلام الخبيث عبر هجمات حقن الشيفرة المصدريّة عبر موقع وسيط أو ما يعرف بــِ XSS.','This setting will deny any requests that use a proxy server when posting comments.'=>'يقوم هذا الإعداد برفض الطلبات التي تستخدم خادم وكيل عند إضافة التعليقات.','Disabling trace and track on your site will help prevent HTTP Trace attacks.'=>'يساعد تعطيل التعقيبات (trace and track) في منع هجمات تعقب HTTP.','This hacking technique is usually used together with cross site scripting attacks (XSS).'=>'يتم استخدام طريقة الاختراق هذه مع هجمات حقن الشيفرة المصدريّة عبر موقع وسيط (XSS).','HTTP Trace attack (XST) can be used to return header requests and grab cookies and other information.'=>'يُمكن أن يتم استخدام هجوم تعقب HTTP أو هجوم XST لاسترداد ترويسة الطلبات والحصول على الكوكيز ومعلومات أخرى.','This feature will prevent the listing of contents for all directories.'=>'تقوم هذه الميزة بمنع سرد محتويات المسارات.','By default, an Apache server will allow the listing of the contents of a directory if it doesn\'t contain an index.php file.'=>'بشكل افتراضي، يقوم خادم الأباتشي بسرد محتويات المسار أو المجلد الذي لا يحتوي على ملف index.php بداخله.','NOTE: You should only enable this feature if you are not currently using the XML-RPC functionality on your WordPress installation.'=>'ملاحظة: قم بتفعيل هذه الميزة في حالة عدم استخدام وظيفة XML-RPC  في موقع ووردبريس حالياً.','Apart from the security protection benefit, this feature may also help reduce load on your server, particularly if your site currently has a lot of unwanted traffic hitting the XML-RPC API on your installation.'=>'بالإضافة إلى فائدة الحماية التي تقدمها هذه الميزة، فإنّها أيضاً تساعد بتخفيف الضغط على الخادم، وخصوصاً في حالة وجود الكثير من زيارات الموقع غير المرغوبة التي تستهدف XML-RPC API في موقع الويب الخاص بك.','3) Scanning ports in internal networks to get info from various hosts.'=>'3) تفحص المنافذ في الشبكات الداخلية للحصول على معلومات من أكثر من مستضيف.','2) Hacking internal routers.'=>'2) اختراق الموجهات الداخلية.','1) Denial of Service (DoS) attacks'=>'1) هجوم حجب الخدمة (DoS).','Hackers can exploit various vulnerabilities in the WordPress XML-RPC API in a number of ways such as:'=>'يقوم القراصنة باستغلال ثغرات متنوعة في XML-RPC API الخاص بموقع ووردبريس باستخدام طرق متعددة مثل: ','You are still advised to take a backup of your active .htaccess file just in case.'=>'بالرغم من ذلك، نوصي بأخذ نسخة احتياطية من ملف .htaccess الحالي احترازاً.','The above firewall features will be applied via your .htaccess file and should not affect your site\'s overall functionality.'=>'سيتم تطبيق قواعد الجدار الناري أعلاه بوضعها في ملف .htaccess، ولن يؤثر ذلك على وظيفة عمل الموقع بشكل عام.','4) Protect your wp-config.php file by denying access to it.'=>'4) حماية ملف wp-config.php من خلال رفض الوصول إليه.','2) Disable the server signature.'=>'2) تعطيل توقيع الخادم.','1) Protect your htaccess file by denying access to it.'=>'1) حماية ملف .htaccess من خلال رفض الوصول إليه.','This setting will implement the following basic firewall protection mechanisms on your site:'=>'تقوم هذه الإعدادات بتطبيق الآلية التالية لتحقيق حماية الجدار الناري في الموقع:','Enter your system log file name. (Defaults to error_log)'=>'قم بإدخال اسم ملف السجلات في الاستضافة الخاصة بك (الافتراضي: error_log )','Enter System Log File Name'=>'قم بإدخال اسم ملف سجل النظام','Depending on the nature and cause of the error or warning, your hosting server can create multiple instances of this file in numerous directory locations of your WordPress installation.'=>'يقوم مزود الاستضافة بإنشاء نسخ متعددة من هذا الملف في مسارات متعددة في موقع ووردبريس حسب طبيعة وسبب الأخطاء والتحذيرات.','Sometimes your hosting platform will produce error or warning logs in a file called "error_log".'=>'يقوم مزود الاستضافة في بعض الأحيان بتوليد سجلات التحذير والأخطاء في ملف يسمّى "error_log".','This feature will disable the ability for people to edit PHP files via the dashboard.'=>'تقوم هذه الميزة بتعطيل القدرة على تعديل ملفات PHP من خلال لوحة إدارة موقع ووردبريس.','This is often the first tool an attacker will use if able to login, since it allows code execution.'=>'إذا استطاع القراصنة تسجيل الدخول بالموقع، ستكون هذه هي الأداة الأولى التي سيقومون باستخدامها، لأنّها تسمح بتنفيذ التعليمات البرمجية.','File/Folder'=>'الملف/المجلد','This feature will scan the critical WP core folders and files and will highlight any permission settings which are insecure.'=>'تقوم هذه الميزة بتفحص أذونات مجلدات ملفات موقع ووردبريس الأساسية، وكما تقوم بتعليم إعدادات الأذونات غير الآمنة.','However, sometimes people or other plugins modify the various permission settings of certain core WP folders or files such that they end up making their site less secure because they chose the wrong permission values.'=>'ولكن، في بعض الأحيان يقوم بعض الأشخاص أو الإضافات بالتعديل على إعدادات الأذونات المختلفة الخاصة بمجلدات وملفات أساس موقع ووردبريس، مما يقلل من حماية الموقع بسبب وضع قيم الأذونات الخاطئة لهذه الملفات أو المجلدات.','Your WP installation already comes with reasonably secure file permission settings for the filesystem.'=>'يتم تثبيت ووردبريس بإعدادات أذونات آمنة ومعقولة لملفات موقع ووردبريس.','File'=>'الملف','Site response time monitoring'=>'مراقبة فترة استجابة الموقع','Site uptime monitoring'=>'مراقبة فترة تشغيل الموقع','Often when malware code has been inserted into your site you will normally not notice anything out of the ordinary based on appearances, but it can have a dramatic effect on your site\'s search ranking.'=>'غالباً لن تلاحظ أي تغيير في موقع الويب عند حقن أي كود خبيث بالموقع، ولكن لذلك تأثير كبير على ترتيب الموقع في صفحة نتائج محرك البحث.','somedirectory'=>'somedirectory','Example: If you want the scanner to ignore certain files in different directories or whole directories, then you would enter the following:'=>'مثال: إذا أردت أن يقوم الماسح بتجاهل ملفات معينة في مسارات مختلفة أو تجاهل المسارات كاملةَ، عليك إدخال التالي: ','Enter each file or directory on a new line which you wish to exclude from the file change detection scan.'=>'قم بإدخال كل مسار الذي تريد استثنائه من عملية التفحص للكشف عن تغيير الملفات على سطر مستقل.','Enter each file type or extension on a new line which you wish to exclude from the file change detection scan.'=>'قم بإدخال كل نوع أو امتداد من الملفات التي تريد استثنائها من عملية التفحص للكشف عن تغيير الملفات على سطر مستقل.','Set the value for how often you would like a scan to occur'=>'قم بتحديد قيمة عدد المرات القيام بعملية التفحص','The "File Change Detection Feature" will notify you of any file change which occurs on your system, including the addition and deletion of files by performing a regular automated or manual scan of your system\'s files.'=>'تقوم "ميزة الكشف عن تغيير الملفات" بإشعارك بأي تغيير ملف تم في نظامك، متضمناً الإضافة والحذف على أي ملف بوساطة القيام بعملية تفحص دورية تلقائية أو يدوية لملفات النظام.','Being informed of any changes in your files can be a good way to quickly prevent a hacker from causing damage to your website.'=>'يعتبر معرفة وجود أي تغييرات بملفات موقع الويب الخاص بك طريقة جيدة لمنع القراصنة بشكل سريع من التسبب بأي ضرر في موقع الويب الخاص بك.','The %s table records which had references to the old DB prefix were updated successfully!'=>'تم تعديل قيود الجدول %s التي تشير إلى البادئة القديمة بنجاح!','The options table records which had references to the old DB prefix were updated successfully!'=>'تم تعديل قيود جدول options التي تشير إلى البادئة القديمة بنجاح!','wp-config.php file was updated successfully!'=>'تم تعديل ملف wp-config.php بنجاح!','%s tables had their prefix updated successfully!'=>'تم تغيير بادئة الجداول %s بنجاح!','Please change the prefix manually for the above tables to: %s'=>'يرجى تغيير البادئة بشكل يدوي للجداول أعلاه: %s','%s table name update failed'=>'فشل في تعديل اسم الجدول %s','A backup copy of your wp-config.php file was created successfully!'=>'تمت عملية النسخ الاحتياطي لملف wp-config.php بنجاح!','Starting DB prefix change operations.....'=>'البدء بعملية تغيير بادئة قاعدة البيانات','Error - Could not get tables or no tables found!'=>'خطأ - لا يمكن الحصول على الجداول أو لم يتم العثور على أي جداول','Weeks'=>'أسابيع','Days'=>'أيام','Hours'=>'ساعات','OR'=>'أو','It is recommended that you perform a %s before using this feature'=>'يُوصى بالقيام بــِ  %s قبل استخدام هذه الميزة','This feature allows you to easily change the prefix to a value of your choice or to a random value set by this plugin.'=>'تقوم هذه الميزة بتغيير بادئة قاعدة البيانات إلى قيمة من اختيارك أو إلى قيمة عشوائية مولدة بوساطة هذه الإضافة.','One way to add a layer of protection for your DB is to change the default WordPress table prefix from "wp_" to something else which will be difficult for hackers to guess.'=>'تكون أحد الطرق لحماية قاعدة بيانات ووردبريس بتغيير البادئة الافتراضية لقاعدة البيانات "wp_" لبادئة أخرى يُصعب على القراصنة تخمينها.','Please enter a value for the DB prefix.'=>'يرجى إدخال قيمة في بادئة قاعدة البيانات.','On'=>'مفعّل','Settings'=>'الإعدادات','Date'=>'التاريخ','There are no IP addresses currently locked out.'=>'لا يوجد أي عناوين الانترنت IPs محظورة حاليّاً.','There are no other users currently logged in.'=>'لا يوجد أي مستخدمين مسجّلين الدخول حاليّاً في الموقع.','Number of users currently logged into your site (including you) is:'=>'عدد المستخدمين المسجلين الدخول حالياً في الموقع (متضمناً أنت):','There are no other site-wide users currently logged in.'=>'لا يوجد أي مستخدمين مسجّلين الدخول حاليّاً في الموقع.','Go to the %s menu to see more details'=>'الانتقال إلى قائمة %s لعرض التفاصيل','Your new WordPress login URL is now:'=>'رابط تسجيل الدخول الجديد: ','The %s feature is currently active.'=>'ميزة %s مفعّلة حاليّاً.','IP'=>'عنوان الانترنت IP','User'=>'المستخدم','Below is the current status of the critical features that you should activate on your site to achieve a minimum level of recommended security'=>'فيما يلي الحالة الحالية للمزايا المهمة التي يجب تفعيلها في موقع الويب الخاص بك لتحقيق الحد الأدنى للحماية المُوصى بها','This feature will deny login access for all IP addresses which are not in your whitelist as configured in the settings below.'=>'ترفض هذه الميزة الوصول لكل عناوين الانترنت IPs غير الموجودة في القائمة البيضاء كما يتم تعيينه في الإعدادات أدناه.','If you do not use the WordPress password protection feature for your posts or pages then it is highly recommended that you leave this checkbox disabled.'=>'يُوصى بشدة بعدم بتحديد هذا في حالة عدم استخدام ميزة حماية منشورات ووردبريس بكلمة مرور.','Helpful Tip:'=>'نصيحة مساعدة','Redirecting a hacker or malicious bot back to "http://127.0.0.1" is ideal because it deflects them back to their own local host and puts the load on their server instead of yours.'=>'من المثالي توجيه القراصنة أو البوت الضار إلى "http://127.0.0.1" لأنّ ذلك يرجعهم إلى الخادم الخاص بهم وهذا يزيد من الضغط على الخادم الخاص بهم وليس الخادم المستضيف لموقع الويب الخاص بك.','It\'s a good idea to not redirect attempted brute force login attempts to your site because it increases the load on your server.'=>'من الجيد عدم إعادة توجيه محاولة تسجيل هجوم القوة العمياء إلى موقع الويب الخاص بك لأنّ ذلك يزيد من حجم الضغط على الخادم المستضيف لموقع الويب الخاص بك.','Useful Tip:'=>'نصيحة مفيدة: ','This field will default to: http://127.0.0.1 if you do not enter a value.'=>'القيمة الافتراضية للحقل: http://127.0.0.1 في حالة عدم إدخالك لأي قيمة.','Specify a URL to redirect a hacker to when they try to access your WordPress login page.'=>'قم بتحديد رابط ليتم إعادة توجيه القراصنة إليه عند محاولته الوصول إلى صفحة تسجيل الدخول.','Re-direct URL'=>'رابط إعادة التوجيه','Any person trying to access your login page who does not have the special cookie in their browser will be automatically blocked.'=>' بشكل أتوماتيكي سيتم حظر أي شخص ممن يحاول تسجيل الدخول بموقع الويب الخاص بك ولا يملك سجل الكوكيز المعيّن في متصفحه.','1) Enable the checkbox.'=>'1) تحديد المربع.','To use this feature do the following:'=>'لاستخدام هذه الميزة، قم بالتالي: ','This feature will deny access to your WordPress login page for all people except those who have a special cookie in their browser.'=>'تقوم هذه الميزة برفض الوصول لصفحة تسجيل الدخول لأولئك الأشخاص الذين ليس لهم سجل كوكيز معيّن في متصفحاتهم. ','Due to the fact that at any one time there may be many concurrent login attempts occurring on your site via malicious automated robots, this also has a negative impact on your server\'s memory and performance.'=>'قد يحدث عدة محاولات متزامنة لتسجيل الدخول في موقع الويب الخاص بك من قبل الروبوتات المأتمتة الضارّة، ولهذا تأثير سلبي على أداء وذاكرة الخادم المستضيف لموقع الويب الخاص بك.','A Brute Force Attack is when a hacker tries many combinations of usernames and passwords until they succeed in guessing the right combination.'=>'يكون هجوم القوة العمياء عندما يحاول القراصنة بتخمين مجموعات من أسماء المستخدمين وكلمات المرور حتى ينجحون بتخمين اسم المستخدم وكلمة المرور الصحيحين.','You have successfully saved cookie based brute force prevention feature settings.'=>'تم حفظ إعدادات ميزة منع هجوم القوة العمياء بالاعتماد على سجل الكوكيز بنجاح.','simply remember to add a "?%s=1" to your current site URL address.'=>'بكل بساطة تذكّر إضافة "?%s=1" لرابط موقع الويب الخاص بك الحالي.','It is important that you save this URL value somewhere in case you forget it, OR,'=>'من الضروري حفظ هذا الرابط في مكان ما في حالة نسيانه، أو','From now on you will need to log into your WP Admin using the following URL:'=>'من الآن وصاعداً، عليك تسجيل الدخول بموقع الويب الخاص بك باستخدام الرابط الآتي: ','You have successfully enabled the cookie based brute force prevention feature'=>'تم تفعيل ميزة منع هجوم القوة العمياء المعتمد سجل الكوكيز بنجاح.','Your current login URL is:'=>'رابط صفحة تسجيل الدخول الحالي: ','Your WordPress login page URL has been renamed.'=>'تم تغيير رابط صفحة تسجيل الدخول.','You may also be interested in the following alternative brute force prevention features:'=>'قد تكون مهتماً أيضاً بأحد الطرق البديلة التالية لمنع هجوم القوة العمياء:','By doing this, malicious bots and hackers will not be able to access your login page because they will not know the correct login page URL.'=>'عند قيامك بهذا ستمنع كل البوتات الضارّة والقراصنة من الوصول لصفحة تسجيل الدخول، لإنّهم لن يعرفوا الرابط الصحيح لصفحة تسجيل الدخول.','Normally if you wanted to login to WordPress you would type your site\'s home URL followed by wp-login.php.'=>'عادةً ما تُدخل رابط موقع الويب الخاص بك الرئيسي متبوعاً بـــِ wp-login.php لتسجيل الدخول بموقع ووردبريس.','An effective Brute Force prevention technique is to change the default WordPress login page URL.'=>'يعتبر تغيير رابط صفحة تسجيل الدخول الافتراضية طريقة فعّالة لمنع هجمات القوة العمياء.','You cannot use the value "wp-admin" for your login page slug.'=>'لا يمكنك استخدام قيمة "wp-admin" كاسم لطيف لصفحة تسجيل الدخول.','Please enter a value for your login page slug.'=>'يرجى إدخال الاسم اللطيف لصفحة تسجيل الدخول','Honeypot'=>'مصائد الروبوتات','Save Settings'=>'حفظ الإعدادات','Example 2 - A list of more than 1 user agent strings to block'=>'مثال 2 - حظر قائمة أسماء وكلاء المستخدم','Example 1 - A single user agent string to block:'=>'مثال 1- حظر اسم وكيل المستخدم واحد: ','Each user agent string must be on a new line.'=>'يجب إدراج كل اسم وكيل المستخدم على سطر مستقل.','Enter one or more user agent strings.'=>'إدخال اسم وكيل المستخدم واحد أو أكثر.','Example 3: 195.*.*.*'=>'مثال 3: 195.*.*.*','Example 2: 195.47.*.*'=>'مثال 2: 195.47.*.*','Example 1: 195.47.89.*'=>'مثال 1: 195.47.89.*','Each IP address must be on a new line.'=>'يجب إدراج كل عنوان انترنت IP على سطر مستقل','More Info'=>'المزيد من المعلومات','Enter one or more IP addresses or IP ranges.'=>'إدخال عنوان انترنت واحد IP أو عدة عناوين انترنت IPs أو مجال معين من عناوين الانترنت IPs:','This feature will deny total site access for users which have IP addresses or user agents matching those which you have configured in the settings below.'=>'تقوم هذه الميزة برفض وصول المستخدمين أصحاب عناوين الانترنت أو وكلاء المستخدم المتطابقة مع العناوين ووكلاء المستخدم التي تم تعيينها في الإعدادات التالية.','Scanner'=>'عمليات التفحص والبحث','Brute Force'=>'هجوم القوة العمياء','Firewall'=>'الجدار الناري','Database Security'=>'حماية قاعدة البيانات','paging%1$s of %2$s'=>'%1$s من %2$s','%1$s %2$d'=>'%1$s %2$d','Apply'=>'تطبيق','No items found.'=>'لم يتم العثور على أي شيء.','Dashboard'=>'لوحة التحكم الرئيسية','NOTE: If you use Jetpack or the Wordpress iOS or other apps then you should enable this feature but leave the "Completely Block Access To XMLRPC" checkbox unchecked.'=>'ملاحظة: عليك تفعيل هذه الميزة في حالة استخدام إضافة Jetpack أو the WordPress iOS أو أي إضافات أخرى، كما عليك تعطيل ميزة "رفض الوصول إلى XMLRP بشكل كامل"','By leaving this feature enabled you will prevent Jetpack or Wordpress iOS or other apps which need XMLRPC from working correctly on your site.'=>'يؤدي تفعيل هذه الميزة إلى منع إضافة Jetpack أو the WordPress iOS أو أي إضافات أخرى تستخدم وظائف XMLRPC من العمل الصحيح في موقع الويب الخاص بك.']];